// stream-aead — chunked authenticated encryption
// Chunk size: 64 KiB, Key size: 32

const CHUNK = 64 * 1024;

fn derive_stream_key::(password, salt) {
    return @crypto_pbkdf2(password, salt, 100000, 32);
}

fn encrypt_stream::(plaintext, key) {
    let total = @len(plaintext);
    let chunks = [];
    let mut off = 0;
    let mut seq = 0;
    while (off < total) {
        let n = @min(CHUNK, total - off);
        let slice = @str_slice_utf8(plaintext, off, n);
        let mem = @mem_from_bytes(@bytes(slice));
        let nonce = @crypto_random_bytes(12);
        @mem_encrypt(mem, key);
        @push(chunks, {"seq": seq, "nonce": @base64(nonce),
                        "data": @base64(@mem_to_bytes(mem))});
        @free(mem);
        off += n;
        seq += 1;
    }
    return @json_encode({"chunks": chunks, "total": total});
}

fn decrypt_stream::(envelope, key) {
    let env = @json_decode(envelope);
    let chunks = env["chunks"];
    let out = "";
    for i in @range(0, @len(chunks)) {
        let c = chunks[i];
        let cipher = @base64_decode(c["data"]);
        let mem = @mem_from_bytes(cipher);
        @mem_decrypt(mem, key);
        out += @mem_to_string(mem);
        @free(mem);
    }
    return out;
}

fn chunk_count::(envelope) { return @len(@json_decode(envelope)["chunks"]); }
fn version::() { return "1.0.0"; }
